<?php
/**
 * VsoftPOS eBill + Slim Receipt Deploy Script
 * Upload to public/ folder and visit in browser.
 */

die('<!-- Remove this line to enable deployment -->');

$files = [
    __DIR__ . '/../resources/views/sale_pos/partials/show_invoice.blade.php' => '',
    __DIR__ . '/../resources/views/sale_pos/receipts/slim.blade.php' => '',
];

foreach ($files as $path => $b64) {
    $dir = dirname($path);
    if (!is_dir($dir)) {
        mkdir($dir, 0755, true);
    }
    $content = base64_decode($b64);
    file_put_contents($path, $content);
    echo "<p>Deployed: " . basename($path) . " (" . strlen($content) . " bytes)</p>\n";
}

echo "<h2>Done!</h2>";
